-- ROLLBACK for 20261006221000_m820_1_hints.sql — restores the pre-block descriptions (inventory snapshot 20261006).
BEGIN;
UPDATE fields x SET description = 'Full mailing address (street, postal code, city)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_address';
UPDATE fields x SET description = 'Authorized representative of the Auftraggeber' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_contact_person';
UPDATE fields x SET description = 'Legal entity name of the Auftraggeber' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Municipality, utility, association, federal authority, other — determines applicable Schwellenwert (139.000€ vs 214.000€)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_organization_type';
UPDATE fields x SET description = 'Net construction cost estimate per DIN 276; used as plausibility check for engineering fee' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'estimated_construction_cost';
UPDATE fields x SET description = 'Estimated net engineering fee — the primary Auftragswert that triggers EU-threshold check' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'estimated_engineering_fee';
UPDATE fields x SET description = 'Treatment plant, network, pumping station, basin, etc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'facility_type';
UPDATE fields x SET description = 'Brief 2-3 sentence summary of the project' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_description';
UPDATE fields x SET description = 'Municipality or region of the planned project' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Official German designation of the project' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Optional English translation of project name' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_name_en';
UPDATE fields x SET description = 'Internal client reference for the project; root identifier propagated to every downstream worksheet' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Konzept (system-wide planning) or Projekt (concrete measure), per §4.1 distinction (Bild 1)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_type';
UPDATE fields x SET description = 'Date of project registration milestone' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'registration_date';
UPDATE fields x SET description = 'Water industry sector: wastewater, water_supply, flood_protection, waste, other' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'sector';
UPDATE fields x SET description = 'New construction, expansion, rehabilitation, study' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'work_type';
UPDATE fields x SET description = 'Ein privater Auftraggeber ohne Fördermittel ist nicht an das Vergaberecht gebunden (§ 7.2: „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“), kann das Vergabeverfahren aber freiwillig anwenden („Jeder Person steht die Anwendung des Merkblatts frei.“). Ja = alle Vergabeprüfungen gelten wie für einen öffentlichen Auftraggeber (empfohlen, sichere Seite). Nein = die Vergabeprüfungen REQ-07, REQ-08, REQ-10, REQ-22, REQ-26 sind nicht erforderlich — Entscheidung in M820-01 dokumentiert (in der Prüfliste erscheinen sie als erfüllt); Bekanntmachungsdatum und Wartefrist nach § 134 GWB werden ausgeblendet.
[EN] A private client without public funding is not bound by procurement law (§ 7.2: "Procurement law binds clients, or private clients who receive public funding."), but may follow the procedure voluntarily ("Anyone is free to apply the Merkblatt."). Yes = every procurement check applies as for a public client (recommended, safe side). No = the procurement checks REQ-07, REQ-08, REQ-10, REQ-22, REQ-26 are not required — decision documented in M820-01 (they appear as met/passed in the gate list); the EU-notice date and the § 134 GWB standstill fields are hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'vergaberecht_freiwillig_angewendet';
UPDATE compliance_requirements x SET description = 'Project is within the M 820-1 scope (water industry engineering procurement)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.code = 'REQ-01';
UPDATE compliance_requirements x SET description = 'Net total value estimated per pflichtgemäßes Ermessen and transparent objektive Kriterien' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.code = 'REQ-06';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'leistungsumfang_beschreibung';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'auftragswert_geschaetzt';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'umfang_definition_datum';
UPDATE fields x SET description = 'Boolean check: Auftraggeber has communicated decision paths and Gremien-Beteiligung per §4.5' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'decision_paths_documented';
UPDATE fields x SET description = 'Named project leader on Auftraggeber side; must have decision authority per §4.5' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'project_manager_ag';
UPDATE fields x SET description = 'Beteiligten-Matrix (§5.1–5.6, Bild 5): je Beteiligtem eine Zeile — Beteiligter, Rolle/Funktion, Verantwortung, Kommunikationsweg.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_list';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-03-D1 (count_rows über stakeholder_list).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_count';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-03-D2 (je §5-Kategorie 1, wenn mindestens eine Zeile sie trägt); Vorschlag für REQ-04 (heute leere Bedingung auf M820-01) STAGED (m820_1-G-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_kategorien_abgedeckt';
UPDATE equations x SET description = 'Plan 3: Anzahl der Zeilen der Beteiligten-Matrix.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.equation_number = 'M820-03-D1';
UPDATE equations x SET description = 'Plan 3: Anzahl der §5-Kategorien (Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden, Öffentlichkeit), die mindestens eine Zeile tragen (0–5); Vorschlag für REQ-04 STAGED (m820_1-G-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.equation_number = 'M820-03-D2';
UPDATE compliance_requirements x SET description = 'All 5 stakeholder categories per §5 captured (AG, AN, ausf. Firmen, Behörden, Öffentlichkeit)
[Flow 1, 2026-10-06] Blatt / sheet M820-03 „Beteiligten-Matrix“ (vorher / was M820-01 „Projektregistrierung“): die Bestätigung steht dort, wo die Beteiligten erfasst werden (stakeholder_list). § 5 (PDF S. 25): „Bei jeder Planung gibt es einen Auftraggeber und oftmals mehrere Auftragnehmer.“ [EN] The sign-off sits where the parties are entered.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.code = 'REQ-04';
UPDATE fields x SET description = 'Register geprüfter Alternativen (§4.1, §6.3): Alternative, Beschreibung, Bewertung/Ergebnis.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'alternatives_considered';
UPDATE fields x SET description = 'Boolean: Aufgabenbeschreibung is sufficiently unambiguous that all Bewerber understand it the same way (mandatory under §121 Abs. 1 GWB)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'aufgabenbeschreibung_eindeutig';
UPDATE fields x SET description = 'Boolean: needs-assessment for the system concept is completed and documented' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'bedarfsplanung_konzept_complete';
UPDATE fields x SET description = 'Uncertainty band for cost estimates produced during Vorplanung phase. Standard: ±25 %, may be higher in specific cases. Engine should warn if a decision is made on an estimate whose uncertainty band crosses the EU threshold' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'cost_estimate_uncertainty_pct';
UPDATE fields x SET description = 'Target completion date for Bedarfsplanung phase' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'date_bedarfsplanung_complete';
UPDATE fields x SET description = 'Register Qualitätsziele Konzept (Bild 2): Qualitätsziel + Anforderung/Kriterium.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'quality_targets_konzept';
UPDATE compliance_requirements x SET description = 'Concept-level needs-assessment per DIN 18205 completed before procurement' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.code = 'REQ-02';
UPDATE fields x SET description = 'Boolean: project-level needs-assessment completed per §6.4' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.symbol = 'bedarfsplanung_projekt_complete';
UPDATE fields x SET description = 'Register Qualitätsziele Projekt (Bild 3): Qualitätsziel + Anforderung/Kriterium.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.symbol = 'quality_targets_projekt';
UPDATE compliance_requirements x SET description = 'Project-level needs-assessment completed; basis for Aufgabenbeschreibung' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.code = 'REQ-03';
UPDATE fields x SET description = 'Strukturiertes, mehrparteiliges Risikoregister je Zeile ein Risiko (Anhang A, S. 43 + Tab. A.1/A.2): Risikogruppe (eine von 11 gedruckten Gruppen), Beschreibung, Bewertung durch Bauherr/Planer/Betrieb je Eintretenswahrscheinlichkeit 0–10 und Schaden 0–10 (Anker 0/5/10); daraus abgeleitet je Dimension M-Wert (Mittelwert) und S-Abweichung (Stichproben-Standardabw., n−1), Risiko = Eintretenswahrscheinlichkeit × Schaden je Beteiligtem, M-Wert/S-Abw über die Produkte; Maßnahmen (Tab. A.2) inkl. Konsequenzen und Kompetenzregelung. Anzahl/Max/Mittel/Divergenz werden aus dem Register abgeleitet (nicht mehr händisch erfasst).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_register';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_analysis_method';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_analysis_date';
UPDATE fields x SET description = 'Änderungsprotokoll der Risikoanalyse: je Änderung eine Zeile (Datum, Risiko-ID/-Name wie in der Risikoanalyse, Art der Änderung, Bewertung alt/neu, Begründung, Quelle/Version). Die aktuelle Bewertung steht in der Risikoanalyse (Tab. A.1) oben; diese Tabelle dokumentiert, wie sie sich über die Projektphasen geändert hat. Grundlage § 4.7 (PDF S. 24): „Die Risikoanalyse ist über alle Projektphasen fortzuschreiben.“ Die Form der Dokumentation (Zeilen, Spalten) ist eine vom Auftraggeber des Werkzeugs gewünschte Dokumentationshilfe — das Merkblatt druckt die Pflicht zur Fortschreibung, kein Änderungsprotokoll. Nicht verpflichtend, keine Prüfung.
[EN] Change log of the risk analysis: one row per change (date, risk ID / name as used in the analysis, kind of change, old / new rating, reason, source / version). The current assessment stays in the risk analysis (Tab. A.1) above; this table documents how it changed over the project phases. Basis § 4.7: "The risk analysis is to be updated over all project phases." The form of the record (rows, columns) is an owner-requested documentation aid — the Merkblatt prints the duty to update, not a change log. Optional, no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risiko_aenderungen';
UPDATE fields x SET description = 'Ausgabe der Gleichung M820-06-D1 (count_rows(risiko_aenderungen)). Anzahl der vollständigen Zeilen (Datum, Risiko, Art der Änderung, Begründung ausgefüllt). Kein Gate. [EN] Number of complete change rows (date, risk, kind of change, reason filled); no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risiko_aenderungen_count';
UPDATE equations x SET description = 'Anzahl der vollständigen Zeilen des Änderungsprotokolls der Risikoanalyse (Datum, Risiko, Art der Änderung, Begründung ausgefüllt). Kein Gate. [EN] Number of complete rows of the risk-analysis change log; no gate.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.equation_number = 'M820-06-D1';
UPDATE fields x SET description = 'Strukturierter Risiko-Maßnahmenplan je Risiko (Anhang A, Tab. A.2): Risiko, Risikokategorie (eine der 11 Tab.-A.1-Gruppen), Wert, Schäden, Gefährdungsbilder, Bemerkung/Bearbeitungsstand; Liste von Maßnahmen je Typ Technische (T) / Organisatorische (O) / Personelle (P) mit Verantwortung, Durchführung und Überwachung. Maßnahmen-Anzahl (nach Typ) wird aus dem Plan abgeleitet (nicht mehr händisch erfasst).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'risk_mitigation_plan';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'mitigation_plan_approved';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'mitigation_plan_date';
UPDATE compliance_requirements x SET description = 'Systematic risk analysis per Anhang A produced and maintained across project phases
[REQ-05 home, 2026-10-06] Blatt / sheet M820-07 „Risiko-Maßnahmenplan“ (vorher / was M820-04 „Bedarfsplanung Konzept“). Die Prüfung liest risk_register (M820-06, weitergereicht an M820-07 / -25) und risk_mitigation_plan (Feld auf M820-07); auf M820-04 kam keiner der beiden Werte an — die Prüfung wartete dauerhaft. § 4.7 (PDF S. 24): „Die Risikoanalyse ist über alle Projektphasen fortzuschreiben.“ Anhang A (PDF S. 45): Maßnahmenpläne nach Tabelle A.2. [EN] The check reads risk_register (M820-06, passed on to M820-07 / -25) and risk_mitigation_plan (a field on M820-07); neither reached M820-04, so the check waited for good. § 4.7: "The risk analysis is to be updated over all project phases."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.code = 'REQ-05';
UPDATE fields x SET description = 'Mehrfachauswahl anwendbarer Rechtsgrundlagen (§7.1–7.4, Anhang B): AEUV, VRL, GWB, VgV, UVgO, VOL/A, BHO, LHO, GemO, Landesvergabegesetze, HOAI, BGB; eigene Ergänzung möglich. Auswahl abhängig vom EU-Schwellenwert.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'applicable_legal_bases';
UPDATE fields x SET description = 'Whether external Behörden coordination/approval is needed for this project' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'authority_oversight_required';
UPDATE fields x SET description = 'Whether HOAI 2013 applies to this engineering service per §73 VgV' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'hoai_applicable';
UPDATE fields x SET description = 'Boolean affirmation that the Auftragswert estimate was NOT split or under-estimated to evade the EU-threshold procedure' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'auftragswert_manipulation_check';
UPDATE fields x SET description = 'Computed flag: |estimated_engineering_fee - eu_threshold_value| / eu_threshold_value <= cost_estimate_uncertainty_pct/100. Triggers WARN that procedure choice may be wrong if estimate refined' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'cost_estimate_near_threshold';
UPDATE fields x SET description = 'EU thresholds are reviewed and reset by EU regulation every 2 years; engine must validate eu_threshold_value against the current effective edition' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_review_interval_years';
UPDATE fields x SET description = 'EU threshold per VO (EU) 2019/1828 effective 01.01.2020: 139.000 € for federal authorities, 214.000 € for others; updated every 2 years' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_value';
UPDATE fields x SET description = 'Loseausnahme per §3 Abs. 9 VgV: applies if individual lot < 80.000 € net and sum of such lots < 20% of total' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'loseausnahme_applicable';
UPDATE fields x SET description = 'Maximum share (% of total Gesamtwert aller Lose) that may be aggregated under the §3 Abs. 9 VgV lot exception' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_share_threshold_pct';
UPDATE fields x SET description = 'Maximum net value per individual lot for Bauleistungen under the §3 Abs. 9 VgV exception (not directly relevant to Ingenieurleistungen but co-cited)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_construction';
UPDATE fields x SET description = 'Maximum net value per individual lot for Liefer-/Dienstleistungen (incl. Ingenieurleistungen) under the §3 Abs. 9 VgV exception' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_services';
UPDATE fields x SET description = 'Computed: true if Auftragswert reaches/exceeds the applicable EU threshold. Drives VgV-F trigger, TED notice requirement, §134 GWB application' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'oberschwellig_check';
UPDATE fields x SET description = 'oberschwellig if estimated_engineering_fee >= eu_threshold_value, otherwise unterschwellig' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'threshold_status';
UPDATE fields x SET description = 'Plan 3: Tab.-Zwilling neben dem eingetragenen eu_threshold_value (konsumiert von M820-10, gelesen von REQ-07 — Umbindung STAGED m820_1-E-1); 139.000 € für oberste/obere Bundesbehörden, 214.000 € für alle anderen; die Zuordnung der übrigen Organisationstypen zu "für alle anderen" ist m820_1-J-3; der Wert ist zeitgebunden (alle zwei Jahre neu festgesetzt — m820_1-J-1). Abgleich → eu_threshold_konsistent_code (M820-09-D3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_value_anhb23';
UPDATE fields x SET description = 'Plan 3: die im Merkblatt gedruckte Verordnung zum Schwellenwert (Textzwilling zur Nachvollziehbarkeit der Ausgabe); eine neuere Verordnung ist eine neue Tabellen-Edition, nie eine Änderung aus dem Gedächtnis (m820_1-J-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_verordnung_anhb23';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D3 (eu_threshold_value == eu_threshold_value_anhb23); ein Gate auf diesen Wert ist STAGED (m820_1-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_konsistent_code';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D1 (estimated_engineering_fee >= eu_threshold_value); abgeleiteter Zwilling zum manuellen Boolean oberschwellig_check und zum Enum threshold_status — Umstellung von REQ-07 / REQ-08 STAGED (m820_1-G-3, D-4 / D-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'oberschwellig_code';
