UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D4 (Konstante aus S3_9_VGV, locked); das editierbare lot_value_threshold_services bleibt bis zur Ratifizierung (m820_1-D-7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_services_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D5 (Konstante aus S3_9_VGV, locked); das editierbare lot_value_threshold_construction bleibt bis zur Ratifizierung (m820_1-D-8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_construction_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D6 (Konstante aus S3_9_VGV, locked); das editierbare lot_share_threshold_pct bleibt bis zur Ratifizierung (m820_1-D-9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_share_threshold_pct_calc';
