UPDATE fields x SET description = 'Plan 3: Zeilen je Los (Art, Nettowert, Loseausnahme); Grenze je Los aus S3_9_VGV; Σ / Abgleich / Anteil / Maximum / Verletzungen → lose_* (M820-09-D8 … D13, D15), loseausnahme_code (M820-09-D14; Anteil auf estimated_engineering_fee bezogen) als abgeleiteter Zwilling zum manuellen Boolean loseausnahme_applicable — Umstellung und REQ-24 (heute leere Bedingung auf M820-04) STAGED (m820_1-D-11, G-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D8 (count_rows über lose).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_count';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D9 (sum_rows über lose.netto_wert_eur) — Anzeige-Zwilling zum geschätzten Netto-Gesamtwert estimated_engineering_fee (m820_1-D-25 / J-7); Abgleich → lose_gesamt_ok.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_gesamt_eur';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D15 (|Σ Lose − estimated_engineering_fee| < 0,005); zeigt, ob der "Gesamtwert aller Lose" (L1366) und der "Gesamtauftragswert" (L1368) übereinstimmen (m820_1-J-7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_gesamt_ok';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D10 (Σ über Zeilen mit Loseausnahme).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_sum_eur';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D11 (Σ ausgenommen · 100 / estimated_engineering_fee — L1368 "Gesamtauftragswerts"; die Register-Σ ist die Alternative, m820_1-J-7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_anteil_pct';
