UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D13 (count_rows über ausgenommene Zeilen, deren Nettowert die Grenze je Los erreicht oder überschreitet).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_verletzt';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-09-D14; Zwilling zum manuellen Boolean loseausnahme_applicable (konsumiert von M820-10) — Umstellung und REQ-24 STAGED (m820_1-D-11, G-4). Anteil bezogen auf estimated_engineering_fee (L1368); ohne eingetragene Lose bleibt der Wert offen (kein Phantom-Bestehen).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'loseausnahme_code';
UPDATE equations x SET description = 'Plan 3: 1 wenn der geschätzte Netto-Gesamtwert den EU-Schwellenwert erreicht oder übersteigt (§ 8.6 "Erreicht oder übersteigt"), sonst 0; Zwilling zu oberschwellig_check / threshold_status — REQ-07 / REQ-08 STAGED (m820_1-G-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D1';
UPDATE equations x SET description = 'Plan 3: Summe der Nettowerte der Lose mit Loseausnahme (nicht gesetzte Kästchen zählen 0).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D10';
UPDATE equations x SET description = 'Plan 3: Anteil der ausgenommenen Lose am geschätzten Netto-Gesamtwert (estimated_engineering_fee, L1368 "Gesamtauftragswerts") in Prozent (Grenze 20 Prozent, "nicht übersteigt"); die Register-Σ als Bezugsgröße ist die Alternative (m820_1-J-7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D11';
UPDATE equations x SET description = 'Plan 3: größter Nettowert eines ausgenommenen Loses (0 ohne Ausnahme); die Grenze je Los steht in der Zeile (grenze_eur, nach Art).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D12';
UPDATE equations x SET description = 'Plan 3: Anzahl der ausgenommenen Lose, deren Nettowert die Grenze je Los ("unter 80000 Euro" / "unter 1 Million Euro") erreicht oder überschreitet — strenge Grenze nach dem Gesetzestext (m820_1-J-6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D13';
UPDATE equations x SET description = 'Plan 3: 1 wenn jedes ausgenommene Los unter seiner Grenze liegt UND die Summe der ausgenommenen Lose höchstens 20 Prozent des geschätzten Netto-Gesamtwerts (estimated_engineering_fee) beträgt, sonst 0; ohne Lose offen; Zwilling zu loseausnahme_applicable — REQ-24 STAGED (m820_1-G-4, D-11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D14';
UPDATE equations x SET description = 'Plan 3: 1 wenn die Σ der eingetragenen Lose dem geschätzten Netto-Gesamtwert entspricht (|Σ − fee| < 0,005; Σ inline, nie auf die neue Ausgabe lose_gesamt_eur verkettet), sonst 0 — Abgleich "Gesamtwertes aller Lose" (L1366) gegen "Gesamtauftragswerts" (L1368), m820_1-J-7 / D-25.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D15';
UPDATE equations x SET description = 'Plan 3: 1 wenn |Netto-Gesamtwert − Schwellenwert| · 100 / Schwellenwert ≤ Ungenauigkeit der Kostenschätzung (%, M820-04 — die ±25 % sind das gedruckte Beispiel, der Wert bleibt Eingabe); Zwilling zu cost_estimate_near_threshold (m820_1-D-6).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D2';
UPDATE equations x SET description = 'Plan 3: 1 wenn der eingetragene EU-Schwellenwert dem Anh.-B.2.3-Wert zum Organisationstyp entspricht, sonst 0; Gate STAGED (m820_1-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D3';
