UPDATE equations x SET description = 'Plan 3: die gedruckte Losgrenze für Bauleistungen (1 Million Euro, "unter") als locked Konstante; Zwilling zu lot_value_threshold_construction (m820_1-D-8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D5';
UPDATE equations x SET description = 'Plan 3: der gedruckte Höchstanteil der ausgenommenen Lose (20 Prozent, "nicht übersteigt") als locked Konstante; Zwilling zu lot_share_threshold_pct (m820_1-D-9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D6';
