UPDATE equations x SET description = 'Plan 3: Σ der eingetragenen Nettowerte aller Lose — Anzeige-Zwilling zum geschätzten Netto-Gesamtwert estimated_engineering_fee (m820_1-D-25 / J-7); Abgleich in M820-09-D15.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D9';
UPDATE compliance_requirements x SET description = 'EU threshold determined; correct value applied per VO (EU) 2019/1828 (139.000 € federal / 214.000 € others)
[Flow 1, 2026-10-06] Blatt / sheet M820-09 „Schwellenwertbestimmung“ (vorher / was M820-04 „Bedarfsplanung Konzept“). Die Prüfung liest eu_threshold_value und threshold_status (beide auf M820-09 eingegeben) sowie estimated_engineering_fee, client_organization_type und vergaberecht_freiwillig_angewendet (M820-01, an M820-09 weitergereicht). Auf M820-04 wartete die Block-Prüfung auf die später einzugebenden Werte und hielt die Freigabe von M820-04 an. § 8.5 (PDF S. 35): Schätzung des Netto-Gesamtwerts; § 8.6 (PDF S. 36): „Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen.“ [EN] The check reads the EU threshold and the threshold status (both entered on M820-09) and three values from M820-01 passed on to M820-09. On M820-04 the block check waited for values entered later and held up the approval of M820-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = 'If lots used: per lot ≤ 80.000 € (services/engineering) or ≤ 1.000.000 € (construction), AND aggregated lot value ≤ 20 % of Gesamtwert aller Lose
[Flow 1, 2026-10-06] Blatt / sheet M820-09 „Schwellenwertbestimmung“ (vorher / was M820-04 „Bedarfsplanung Konzept“): die Bestätigung steht dort, wo die Lose und die Loseausnahme erfasst werden (lose, loseausnahme_code). Anh. B.2.4 (PDF S. 53): „Die Aufteilung in Lose regelt § 3 Abs. 9 VgV“. [EN] The sign-off sits where the lots and the lot exception are entered.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.code = 'REQ-24';
UPDATE fields x SET description = 'Written justification for procedure choice; mandatory for Direktvergabe (Ausnahmefall)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.symbol = 'procedure_rationale';
UPDATE fields x SET description = 'Selected procedure: vgv_f, suchverfahren, direktvergabe, planungswettbewerb. Choice driven by threshold_status' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.symbol = 'procurement_procedure';
UPDATE compliance_requirements x SET description = 'Procurement procedure consistent with threshold_status (oberschwellig → vgv_f; unterschwellig → suchverfahren/direktvergabe)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Optional exclusion grounds per §124 GWB declared in Bekanntmachung when used' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.code = 'REQ-11';
