UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_chairperson';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'kommission_constitution_date';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-16-D1 (count_rows über bewertungskommission_members); Zwilling zum manuellen bewertungskommission_size (gelesen von REQ-09) — Umstellung STAGED (m820_1-D-14, G-8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_size_calc';
