UPDATE fields x SET description = 'Plan 3: Zeilen je Verhandlungsgespräch; Ausgaben negotiation_rounds_calc (max Runde, M820-20-D1), verhandlungsgespraeche_count (-D2), protokolle_unsigniert_count (-D3) als Zwillinge zum Skalarsatz negotiation_rounds / verhandlung_datum / verhandlung_thema / verhandlung_ergebnis / protokoll_signiert — Umstellungen und REQ-20 STAGED (m820_1-D-20 … D-24, G-10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlungsrunden';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-20-D1 (max_rows über runde; ohne Zeile offen); Zwilling zu negotiation_rounds (gelesen von REQ-20) — m820_1-D-20 / G-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'negotiation_rounds_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-20-D2 (count_rows über verhandlungsrunden) — "Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlungsgespraeche_count';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-20-D3 (count_rows über protokoll_signiert = false; ein nicht gesetztes Kästchen zählt als nicht signiert).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'protokolle_unsigniert_count';
UPDATE equations x SET description = 'Plan 3: Anzahl der Verhandlungsrunden = höchste eingetragene Rundennummer (ohne Zeile offen); Zwilling zu negotiation_rounds (REQ-20 ≥ 1) — m820_1-D-20 / G-10.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D1';
UPDATE equations x SET description = 'Plan 3: Anzahl der dokumentierten Verhandlungsgespräche (Runde × Bieter).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D2';
UPDATE equations x SET description = 'Plan 3: Anzahl der Verhandlungsgespräche ohne signiertes Protokoll (ein nicht gesetztes Kästchen zählt als nicht signiert); Zwilling zum Boolean protokoll_signiert — m820_1-D-24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D3';
