UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'haftpflicht_versicherungssumme';
