UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-22-D1 (Stufenkette über TABD1 nach estimated_construction_cost; Baukosten über 50 Mio. € haben keine gedruckte Zeile → offen, m820_1-J-2); Anhaltswert (RBBau-Empfehlung, L1454 / L1629) neben dem eingetragenen liability_insurance_personenschaden (M820-13) und haftpflicht_versicherungssumme — m820_1-D-1 … D-3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_personen_tabd1';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-22-D2 (Stufenkette über TABD1; über 50 Mio. € offen — m820_1-J-2); Anhaltswert neben dem eingetragenen liability_insurance_sonstige (M820-13) — m820_1-D-2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_sonstige_tabd1';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-22-D3 (liability_insurance_personenschaden ≥ Tab.-D.1-Wert, Kette inline); Vorschlag für REQ-13 (heute leere Bedingung auf M820-10) STAGED (m820_1-G-11) — Anhaltswert, daher warn.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_personen_ok';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung M820-22-D4 (liability_insurance_sonstige ≥ Tab.-D.1-Wert, Kette inline); Vorschlag für REQ-13 STAGED (m820_1-G-11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_sonstige_ok';
UPDATE equations x SET description = 'Plan 3: Deckungssumme Personenschäden nach Tab. D.1 zur Baukostenstufe (jede Stufe und jeder Betrag aus TABD1; über 50 Mio. € keine gedruckte Zeile → offen, m820_1-J-2); Anhaltswert (RBBau-Empfehlung) — Zwilling zu liability_insurance_personenschaden / haftpflicht_versicherungssumme (m820_1-D-1 / D-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D1';
UPDATE equations x SET description = 'Plan 3: Deckungssumme sonstige Schäden nach Tab. D.1 zur Baukostenstufe (über 50 Mio. € offen, m820_1-J-2); Zwilling zu liability_insurance_sonstige (m820_1-D-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D2';
UPDATE equations x SET description = 'Plan 3: 1 wenn die geforderte Deckungssumme Personenschäden den Tab.-D.1-Anhaltswert erreicht (Kette inline, nie auf eine neue Ausgabe verkettet); Vorschlag für REQ-13 STAGED (m820_1-G-11, warn).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D3';
UPDATE equations x SET description = 'Plan 3: 1 wenn die geforderte Deckungssumme sonstige Schäden den Tab.-D.1-Anhaltswert erreicht (Kette inline); Vorschlag für REQ-13 STAGED (m820_1-G-11, warn).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D4';
UPDATE fields x SET description = 'Date contract was signed (Auftragserteilung). Must respect 15/10 day standstill' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'award_date';
UPDATE fields x SET description = 'Boolean computed risk flag: true if information letters under §134 GWB were omitted or incomplete. Per §135 GWB this renders the contract ''von Anfang an unwirksam''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'contract_invalidity_135_gwb_risk';
UPDATE fields x SET description = 'Name of the bidder receiving the Zuschlag' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'contractor_auftragnehmer';
UPDATE fields x SET description = 'Target date for Auftragserteilung' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'date_contract_award_target';
UPDATE fields x SET description = 'Whether information letters under §134 GWB were sent electronically. Drives standstill period: 15 d (postal) vs 10 d (electronic)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'electronic_transmission';
UPDATE fields x SET description = 'Boolean: §134 GWB information letters sent to non-selected bidders with substantive (non-formulaic) reasons' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'information_letters_sent';
UPDATE fields x SET description = 'Computed: 15 if electronic_transmission==false, else 10. Validation_Rule RULE-007 compares standstill_period_days against this value' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'required_standstill_days';
UPDATE fields x SET description = 'Standstill period before contract signature: 15 calendar days standard, 10 if electronic transmission' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'standstill_period_days';
UPDATE fields x SET description = 'Plan 3: Tab.-Zwilling neben dem eingetragenen required_standstill_days (konsumiert von M820-24 — Umbindung STAGED m820_1-E-2); Schlüssel = electronic_transmission (Boolean, stringifiziert). REQ-22 prüft standstill_period_days weiterhin je Zweig.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'required_standstill_days_gwb';
UPDATE compliance_requirements x SET description = 'Information letters sent to non-selected bidders with substantive reasons; standstill 15/10 days' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.code = 'REQ-22';
UPDATE compliance_requirements x SET description = 'Information letters under §134 GWB were sent in full to all non-selected bidders; otherwise the contract is per §135 GWB ''von Anfang an unwirksam'' (void ab initio)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.code = 'REQ-26';
