UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'alle_unterlagen_archiviert';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'vergabeakte_unterzeichnet';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'archive_location';
UPDATE fields x SET description = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'final_signoff_date';
UPDATE compliance_requirements x SET description = 'Vergabevermerk per §8 VgV documented following Anhang F structure' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.code = 'REQ-23';
UPDATE fields x SET description = 'Overall verdict: compliant / compliant_with_conditions / not_compliant / insufficient_data' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.symbol = 'compliance_verdict';
UPDATE fields x SET description = 'Final lessons learned for organisational improvement' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.symbol = 'lessons_learned';
UPDATE compliance_requirements x SET description = 'Qualitätsziele per Bild 2 (Konzept) and Bild 3 (Projekt) achieved at compliance check' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.code = 'REQ-25';
